154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
157	        Owner owner = this.clinicService.findOwnerById(ownerId);
158	        if (owner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        HttpHeaders headers = new HttpHeaders();
162	        Pet pet = petMapper.toPet(petFieldsDto);
163	        owner.setId(ownerId);
164	        pet.setOwner(owner);
165	        pet.getType().setName(null);
166	        this.clinicService.savePet(pet);
167	        PetDto petDto = petMapper.toPetDto(pet);
168	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
169	            .buildAndExpand(pet.getId()).toUri());
170	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner != null) {
178	            Pet currentPet = this.clinicService.findPetById(petId);
179	            if (currentPet != null) {
180	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
181	                currentPet.setName(petFieldsDto.getName());
182	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
183	                this.clinicService.savePet(currentPet);
184	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
185	            }
186	        }
187	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
193	        HttpHeaders headers = new HttpHeaders();
194	        Visit visit = visitMapper.toVisit(visitFieldsDto);
195	        Pet pet = new Pet();
196	        pet.setId(petId);
197	        visit.setPet(pet);
198	        this.clinicService.saveVisit(visit);
199	        VisitDto visitDto = visitMapper.toVisitDto(visit);
200	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
201	            .buildAndExpand(visit.getId()).toUri());
202	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
203	    }
204	
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner != null) {
211	            Pet pet = owner.getPet(petId);
212	            if (pet != null) {
213	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
214	            }
215	        }
216	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	    }
218	
219	    /**
220	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
221	     * The address is normalized in place (so a required-field check that follows rejects an
222	     * address blank after normalization), the required fields are checked, the telephone and
223	     * email are normalized in place, and the resulting telephone is rejected when it already
224	     * belongs to another owner. Each rule
225	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
226	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
227	     * to be mapped and saved.
228	     *
229	     * @param ownerFieldsDto the submitted owner fields, normalized in place
230	     */
231	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto) {
232	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
233	        validateRequiredFields(ownerFieldsDto);
234	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
235	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
236	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
237	        rejectDuplicateHousehold(ownerFieldsDto);
238	    }
239	
240	    /**
241	     * Builds the customer code assigned to a newly created owner. The code is formatted as
242	     * {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the upper-cased first three letters of
243	     * the owner's last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to
244	     * one more than the current number of owners. For example the seventh owner named
245	     * {@code 'Smith'} is assigned {@code 'SMI-0007'}.
246	     *
247	     * @param lastName the owner's last name
248	     * @return the formatted customer code
249	     */
250	    private String nextCustomerCode(String lastName) {
251	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
252	        long sequence = this.clinicService.findAllOwners().size() + 1L;
253	        return String.format("%s-%04d", last3, sequence);
254	    }
255	
256	    /**
257	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
258	     * with the owner being created, compared case-insensitively. The count is taken before the
259	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
260	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
261	     *
262	     * @param firstName the first name of the owner being created
263	     * @param lastName the last name of the owner being created
264	     * @return the number of pre-existing owners sharing the same first and last name
265	     */
266	    private int countNamesakes(String firstName, String lastName) {
267	        return (int) this.clinicService.findAllOwners().stream()
268	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
269	                && lastName.equalsIgnoreCase(existing.getLastName()))
270	            .count();
271	    }
272	
273	    /**
274	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
275	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
276	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
277	     * the names of every offending field, which the exception advice renders as a 400 response
278	     * with an {@code errors} array.
279	     *
280	     * @param ownerFieldsDto the submitted owner fields
281	     */
282	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
283	        List<String> missing = new ArrayList<>();
284	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
285	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
286	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
287	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
288	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
289	        if (!missing.isEmpty()) {
290	            throw new RequiredFieldsMissingException(missing);
291	        }
292	    }
293	
294	    private void addIfBlank(List<String> missing, String fieldName, String value) {
295	        if (value == null || value.isBlank()) {
296	            missing.add(fieldName);
297	        }
298	    }
299	
300	    /**
301	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
302	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
303	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
304	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
305	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
306	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
307	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
308	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
309	     *
310	     * @param telephone the submitted telephone value
311	     * @return the normalized E.164 telephone
312	     */
313	    private String normalizeTelephone(String telephone) {
314	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
315	        String e164;
316	        if (cleaned.startsWith("+")) {
317	            e164 = "+" + cleaned.substring(1);
318	        } else {
319	            String national = cleaned;
320	            if (national.startsWith("0")) {
321	                national = national.substring(1);
322	            }
323	            e164 = "+61" + national;
324	        }
325	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
326	            throw new InvalidFieldsException(List.of("telephone"));
327	        }
328	        return e164;
329	    }
330	
331	    /**
332	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
333	     * and a domain containing at least one dot, none of the parts holding whitespace or a
334	     * second {@code @}.
335	     */
336	    private static final java.util.regex.Pattern EMAIL_PATTERN =
337	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
338	
339	    /**
340	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
341	     * accepted and returned unchanged. When present it must be a syntactically valid address;
342	     * the value is stored and returned lower-cased. When present but invalid an
343	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
344	     * response naming the {@code email} field.
345	     *
346	     * @param email the submitted email value, or {@code null} when omitted
347	     * @return the lower-cased email, or {@code null} when none was supplied
348	     */
349	    private String normalizeEmail(String email) {
350	        if (email == null) {
351	            return null;
352	        }
353	        String trimmed = email.trim();
354	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
355	            throw new InvalidFieldsException(List.of("email"));
356	        }
357	        return trimmed.toLowerCase(java.util.Locale.ROOT);
358	    }
359	
360	    /**
361	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
362	     * The telephone is stored in its normalized E.164 form, so a plain equality check
363	     * against every owner's telephone compares E.164 values. When a match is found a
364	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
365	     * 409 Conflict response.
366	     *
367	     * @param telephone the normalized telephone of the owner being created
368	     */
369	    private void rejectDuplicateTelephone(String telephone) {
370	        boolean taken = this.clinicService.findAllOwners().stream()
371	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
372	        if (taken) {
373	            throw new DuplicateTelephoneException(telephone);
374	        }
375	    }
376	
377	    /**
378	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
379	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
380	     * for how that identity is compared). A request may bypass this rule by setting
381	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
382	     * When a household mate is found and the request did not opt in a
383	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
384	     * Conflict response.
385	     *
386	     * @param ownerFieldsDto the submitted owner fields
387	     */
388	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
389	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
390	            return;
391	        }
392	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
393	        if (taken) {
394	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
395	        }
396	    }
397	
398	    /**
399	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
400	     * set to {@code true}. The identifier is derived deterministically from the owner's
401	     * household identity (its {@code lastName} and {@code address}, see
402	     * {@link #householdIdFor(String, String)}), so every owner in the same household resolves to
403	     * the same stable value. The new owner receives that value, and any existing household mates
404	     * that do not yet carry it are updated so the whole household shares one identifier. When the
405	     * request did not opt in the owner is left without a household identifier.
406	     *
407	     * @param owner the newly created owner, mutated in place with its household identifier
408	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
409	     */
410	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
411	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
412	            return;
413	        }
414	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
415	        owner.setHouseholdId(householdId);
416	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
417	            if (!householdId.equals(mate.getHouseholdId())) {
418	                mate.setHouseholdId(householdId);
419	                this.clinicService.saveOwner(mate);
420	            }
421	        }
422	    }
423	
424	    /**
425	     * Derives the stable {@code householdId} shared by every owner in the household identified by
426	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
427	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
428	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
429	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
430	     *
431	     * @param lastName the household's last name
432	     * @param address the household's address
433	     * @return the deterministic household identifier
434	     */
435	    private String householdIdFor(String lastName, String address) {
436	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
437	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
438	        try {
439	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
440	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
441	            StringBuilder sb = new StringBuilder();
442	            for (int i = 0; i < 8; i++) {
443	                sb.append(String.format("%02X", digest[i]));
444	            }
445	            return "HH-" + sb;
446	        }
447	        catch (java.security.NoSuchAlgorithmException e) {
448	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
449	        }
450	    }
451	
452	    /**
453	     * Finds an existing owner that shares a household with the given {@code lastName} and
454	     * {@code address}. When several owners match, the first one encountered is returned.
455	     *
456	     * @param lastName the last name to match on
457	     * @param address the address to match on
458	     * @return the first owner sharing the household, or empty when none exists
459	     */
460	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
461	        return findHouseholdMates(lastName, address).stream().findFirst();
462	    }
463	
464	    /**
465	     * Finds every existing owner that shares a household with the given {@code lastName} and
466	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
467	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
468	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
469	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
470	     * every rule that reasons about households.
471	     *
472	     * @param lastName the last name to match on
473	     * @param address the address to match on
474	     * @return the owners sharing the household, in encounter order (possibly empty)
475	     */
476	    private List<Owner> findHouseholdMates(String lastName, String address) {
477	        String normalizedLastName = collapseWhitespace(lastName);
478	        String normalizedAddress = normalizeAddress(address);
479	        return this.clinicService.findAllOwners().stream()
480	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
481	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
482	            .toList();
483	    }
484	
485	    /**
486	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
487	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
488	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
489	     *
490	     * @param value the value to collapse, or {@code null}
491	     * @return the whitespace-collapsed value, never {@code null}
492	     */
493	    private String collapseWhitespace(String value) {
494	        if (value == null) {
495	            return "";
496	        }
497	        return value.trim().replaceAll("\\s+", " ");
498	    }
499	
500	    /**
501	     * Common street-type abbreviations expanded during address normalization, keyed by their
502	     * upper-cased token.
503	     */
504	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
505	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
506	
507	    /**
508	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
509	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
510	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
511	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
512	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
513	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
514	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
515	     * everywhere an address is stored or compared.
516	     *
517	     * @param address the submitted address value, or {@code null}
518	     * @return the normalized address, never {@code null}
519	     */
520	    private String normalizeAddress(String address) {
521	        if (address == null) {
522	            return "";
523	        }
524	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
525	        if (collapsed.isEmpty()) {
526	            return "";
527	        }
528	        String[] tokens = collapsed.split(" ");
529	        StringBuilder sb = new StringBuilder(collapsed.length());
530	        for (int i = 0; i < tokens.length; i++) {
531	            if (i > 0) {
532	                sb.append(' ');
533	            }
534	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
535	        }
536	        return sb.toString();
537	    }
538	}
